async function loadTemplate(templatePath,containerSelector){try{console.log(`Loading template from:${templatePath}`);const response=await fetch(templatePath);if(!response.ok){throw new Error(`HTTP error!status:${response.status}`)}const html=await response.text();const container=document.querySelector(containerSelector);if(container){let processedHtml=html;if(html.includes('ser-get-started')||html.includes('get-started-section')){const tempDiv=document.createElement('div');tempDiv.innerHTML=html;const sectionInHTML=tempDiv.querySelector('.ser-get-started');if(sectionInHTML){sectionInHTML.classList.remove('animate-in');sectionInHTML.style.setProperty('opacity','0','important');sectionInHTML.style.setProperty('transform','translateY(30px)','important');sectionInHTML.style.setProperty('transition','opacity 0.6s ease,transform 0.6s ease','important');processedHtml=tempDiv.innerHTML}}container.innerHTML=processedHtml;console.log('Template loaded successfully into:',containerSelector);if(html.includes('ser-get-started')||html.includes('get-started-section')){setTimeout(()=>{if(typeof initGetStartedSection==='function'){initGetStartedSection()}},10)}if(html.includes('get-started-form-section')){setTimeout(()=>{initGetStartedFormSection()},100)}if(html.includes('transform-cta-section')){setTimeout(()=>{initTransformCTASection()},100)}if(html.includes('experience-power-section')||html.includes('ser-experience-power')){setTimeout(()=>{initExperiencePowerSection()},100)}const event=new CustomEvent('templateLoaded',{detail:{templatePath,containerSelector}});document.dispatchEvent(event)}else{console.warn(`Container not found:${containerSelector}`)}}catch(error){console.error('Error loading template:',error);const container=document.querySelector(containerSelector);if(container){container.innerHTML=`<div style="background:#ff0000;color:white;padding:20px;border-radius:8px;margin:20px;"><strong>Error loading template:</strong><br>${error.message}<br><small>Make sure you're running a local server(not opening file directly)</small></div>`}}}function initGetStartedSection(){const section=document.querySelector('.ser-get-started');if(!section){console.warn('Get Started section not found after template load');return}section.setAttribute('data-template-initialized','true');section.classList.remove('animate-in');section.removeAttribute('data-animation-initialized');section.setAttribute('data-animate','true');requestAnimationFrame(()=>{if('IntersectionObserver' in window){const observerOptions={threshold:0.1,rootMargin:'0px 0px-50px 0px'};const sectionObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animate-in');setTimeout(()=>{entry.target.style.removeProperty('opacity');entry.target.style.removeProperty('transform')},650);sectionObserver.unobserve(entry.target)}})},observerOptions);sectionObserver.observe(section);const rect=section.getBoundingClientRect();const windowHeight=window.innerHeight;if(rect.top<windowHeight&&rect.bottom>0){setTimeout(()=>{section.classList.add('animate-in');setTimeout(()=>{section.style.removeProperty('opacity');section.style.removeProperty('transform')},650)},200)}}});console.log('Get Started section template loaded and initialized')}function initGetStartedFormSection(){const section=document.querySelector('.get-started-form-section');if(!section){console.warn('Get Started Form section not found after template load');return}if('IntersectionObserver' in window){const observerOptions={threshold:0.1,rootMargin:'0px 0px-50px 0px'};const sectionObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animate-in');sectionObserver.unobserve(entry.target)}})},observerOptions);sectionObserver.observe(section)}if(typeof window.initGetStartedForm==='function'){setTimeout(()=>{window.initGetStartedForm()},100)}if(typeof initGetStartedFormTransition==='function'){initGetStartedFormTransition()}console.log('Get Started Form section template loaded and initialized')}function initTransformCTASection(){const section=document.querySelector('.transform-cta-section');if(!section){console.warn('Transform CTA section not found after template load');return}section.classList.remove('animate-in');section.style.opacity='0';section.style.transform='translateY(30px)';section.style.transition='opacity 0.8s cubic-bezier(0.25,0.46,0.45,0.94),transform 0.8s cubic-bezier(0.25,0.46,0.45,0.94)';setTimeout(()=>{if('IntersectionObserver' in window){const observerOptions={threshold:0.1,rootMargin:'0px 0px-50px 0px'};const sectionObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animate-in');entry.target.style.opacity='';entry.target.style.transform='';sectionObserver.unobserve(entry.target)}})},observerOptions);sectionObserver.observe(section);const rect=section.getBoundingClientRect();const windowHeight=window.innerHeight;if(rect.top<windowHeight&&rect.bottom>0){section.classList.add('animate-in');section.style.opacity='';section.style.transform=''}}},100);console.log('Transform CTA section template loaded and initialized')}function initExperiencePowerSection(){const section=document.querySelector('.ser-experience-power');if(!section){console.warn('Experience the Power section not found after template load');return}if('IntersectionObserver' in window){const observerOptions={threshold:0.1,rootMargin:'0px 0px-50px 0px'};const sectionObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animate-in');sectionObserver.unobserve(entry.target)}})},observerOptions);sectionObserver.observe(section)}console.log('Experience the Power section template loaded and initialized')}